// Paginate returns a page of binary_keys with total count for offset-based pagination.
// A nil filter paginates all binary_keys.
func (c *binaryKeyClient) Paginate(ctx context.Context, input PaginateInput[BinaryKeyFilter], opts ...func(*CallOptions[BinaryKeyFieldOptions])) (*PaginateResult[BinaryKey], error) {
	options := resolveCallOptions(opts)
	result, err := c.executeQuery(ctx, options.SkipHooks, &hook.QueryContext{
		Op: hook.OpPaginate, Table: TableBinaryKeys, Schema: "",
		Input: input, CallOptions: options,
	}, func(ctx context.Context, q *hook.QueryContext) (any, error) {
		// Internal calls with SkipHooks to prevent nested hook invocation
		internalOpts := func(o *CallOptions[BinaryKeyFieldOptions]) {
			*o = options
			o.SkipHooks = true
		}

		// Total count (delegates to Count — both are always generated)
		totalCount, err := c.Count(ctx, input.Filter, internalOpts)
		if err != nil {
			return nil, fmt.Errorf("paginate binary_keys count: %w", err)
		}

		// Page data via GetMany (handles FieldOptions and relationships)
		binaryKeys, err := c.GetMany(ctx, &GetBinaryKeysInput{
			Filter: input.Filter,
			Sorts:  input.Sort,
			Limit:  &input.Limit,
			Offset: &input.Offset,
		}, internalOpts)
		if err != nil {
			return nil, fmt.Errorf("paginate binary_keys: %w", err)
		}

		return &PaginateResult[BinaryKey]{
			Items:      binaryKeys,
			TotalCount: totalCount,
			Offset:     input.Offset,
			Limit:      input.Limit,
			HasMore:    int64(input.Offset+input.Limit) < totalCount,
		}, nil
	})
	if err != nil {
		return nil, err
	}
	return result.(*PaginateResult[BinaryKey]), nil
}

// Connection returns a Relay-style cursor-paginated connection of binary_keys.
// Sort order is determined by cursor_keys — custom sorts are not supported.
// Use Paginate for custom sort orders.
func (c *binaryKeyClient) Connection(ctx context.Context, input ConnectionInput[BinaryKeyFilter], opts ...func(*CallOptions[BinaryKeyFieldOptions])) (*Connection[BinaryKey], error) {
	options := resolveCallOptions(opts)

	if options.LockMode != sql.LockNone {
		return nil, fmt.Errorf("connection binary_keys: LockMode is unsupported on sqlite dialect")
	}
	result, err := c.executeQuery(ctx, options.SkipHooks, &hook.QueryContext{
		Op: hook.OpConnection, Table: TableBinaryKeys, Schema: "",
		Input: input, CallOptions: options,
	}, func(ctx context.Context, q *hook.QueryContext) (any, error) {
		// Internal calls with SkipHooks to prevent nested hook invocation
		internalOpts := func(o *CallOptions[BinaryKeyFieldOptions]) {
			*o = options
			o.SkipHooks = true
		}

		// Validate: first and last are mutually exclusive
		if input.First != nil && input.Last != nil {
			return nil, ErrInvalidCursor
		}

		// Total count (separate COUNT query — no cursor conditions)
		totalCount, err := c.Count(ctx, input.Filter, internalOpts)
		if err != nil {
			return nil, fmt.Errorf("connection binary_keys count: %w", err)
		}

		// Decode cursors and build keyset conditions
		var keysetConds []sql.Condition
		if input.After != nil {
			cursor, err := decodeCursor(*input.After)
			if err != nil {
				return nil, ErrInvalidCursor
			}
			keysetConds = append(keysetConds, cursorKeyset(c.dialect, c.cursorKeys, cursor, ">"))
		}
		if input.Before != nil {
			cursor, err := decodeCursor(*input.Before)
			if err != nil {
				return nil, ErrInvalidCursor
			}
			keysetConds = append(keysetConds, cursorKeyset(c.dialect, c.cursorKeys, cursor, "<"))
		}

		// Direction and limit
		limit := c.pageSize
		ascending := true
		if input.First != nil {
			limit = *input.First
		} else if input.Last != nil {
			limit = *input.Last
			ascending = false
		}

		// Fetch limit+1 rows via GetMany (handles FieldOptions, O2O joins, relationships, soft delete)
		connLimit := limit + 1
		binaryKeys, err := c.GetMany(ctx, &GetBinaryKeysInput{
			Filter:     input.Filter,
			Sorts:      cursorSorts(c.cursorKeys, ascending),
			Limit:      &connLimit,
			conditions: keysetConds,
			// Each edge's cursor is encoded from the row it wraps, so the cursor
			// keys have to survive a narrowed FieldOptions — otherwise the
			// encoder reads fields the SELECT never filled and every cursor
			// carries zero values.
			requiredColumns: c.cursorKeys,
		}, internalOpts)
		if err != nil {
			return nil, fmt.Errorf("connection binary_keys: %w", err)
		}

		// Trim extra row and determine page boundaries
		hasMore := len(binaryKeys) > limit
		if hasMore {
			binaryKeys = binaryKeys[:limit]
		}

		// Backward pagination: reverse for ascending cursor order
		if !ascending {
			slices.Reverse(binaryKeys)
		}

		// Build edges with encoded cursors
		edges := make([]Edge[BinaryKey], len(binaryKeys))
		for i, row := range binaryKeys {
			cursor, err := encodeBinaryKeyCursor(c.cursorKeys, row)
			if err != nil {
				return nil, err
			}
			edges[i] = Edge[BinaryKey]{
				Node:   row,
				Cursor: cursor,
			}
		}

		pageInfo := PageInfo{
			HasNextPage:     (ascending && hasMore) || (!ascending && input.Before != nil),
			HasPreviousPage: (!ascending && hasMore) || (ascending && input.After != nil),
		}
		if len(edges) > 0 {
			pageInfo.StartCursor = &edges[0].Cursor
			pageInfo.EndCursor = &edges[len(edges)-1].Cursor
		}

		return &Connection[BinaryKey]{Edges: edges, PageInfo: pageInfo, TotalCount: totalCount}, nil
	})
	if err != nil {
		return nil, err
	}
	return result.(*Connection[BinaryKey]), nil
}

// encodeBinaryKeyCursor encodes cursor key values as a base64 JSON string.
func encodeBinaryKeyCursor(keys []string, b *BinaryKey) (string, error) {
	out := make(map[string]any, len(keys))
	for _, key := range keys {
		switch key {
		case "id":
			out["id"] = b.ID
		case "name":
			out["name"] = b.Name
		case "created_at":
			out["created_at"] = b.CreatedAt
		}
	}
	data, err := json.Marshal(out)
	if err != nil {
		return "", fmt.Errorf("encode binary_key cursor: %w", err)
	}
	return base64.StdEncoding.EncodeToString(data), nil
}

// StreamBinaryKeysInput holds query parameters for streaming binary_keys records.
